(() => {
'use strict';
const M=window.SWHomeModel,W=window.SWWorkspace,$=id=>document.getElementById(id),root=$('page-home');if(!M||!W||!root)return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={home:'<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 10h18"/>',bell:'<path d="M4 17c3-3 2-4 2-8a6 6 0 0 1 12 0c0 4-1 5 2 8ZM10 21h4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',moon:'<path d="M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 21v-3a9 9 0 0 1 18 0v3Z"/>',note:'<path d="M5 3h10l4 4v14H5ZM14 3v6h5M8 12h8M8 16h6"/>',stack:'<path d="m12 3 10 6-10 6L2 9Zm-10 11 10 6 10-6M2 19l10 6 10-6"/>',check:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="m7 11 4 4 7-8"/>',chart:'<rect x="3" y="13" width="4" height="8" rx="1"/><rect x="10" y="8" width="4" height="13" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/>',coins:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 10c0 4 18 4 18 0M3 15c0 4 18 4 18 0"/>',pie:'<path d="M12 3v9h9A9 9 0 1 1 9 3M15 2v7h7a9 9 0 0 0-7-7Z"/>',clock:'<path d="M3 12a9 9 0 1 1 3 7M3 6v6l4 2"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.note}</svg>`;
root.querySelectorAll('[data-hicon]').forEach(n=>n.innerHTML=icon(n.dataset.hicon));
const prefsKey='sw_home_preferences_v1',quickKey='sw_home_quick_v1',formatKey='sw_home_note_format_v1',bookKey='sw_home_notebooks_v1';
const weatherKey='sw_home_weather_city_v1',weatherCities=['Kayseri','İstanbul','Ankara','İzmir','Bursa','Antalya'];
let weatherCity='Kayseri';try{const saved=W.storage.getItem(weatherKey);if(weatherCities.includes(saved))weatherCity=saved;}catch{}
let period=M.monthRange(M.today().slice(0,7)),month=period.start.slice(0,7),taskDay=M.today(),theme='dark',view='detail',notes=[],noteError='',salesData={rows:[],total:null},salesError='',invoice={rows:[]},invoiceStats={rows:[]},saleKey='',quickRaw='',quickSettings={font:'sans',size:14},quickTimer=0,noteTimer=0,activeNote=null,formatRaw=null,formatMap={};
function status(message,error=false){$('homeStatus').textContent=message;$('homeStatus').hidden=!message;$('homeStatus').dataset.error=String(error);}
try{const p=M.read(W.storage,prefsKey,x=>x&&typeof x==='object',{});if(p.start&&p.end)period=M.range(p.start,p.end);month=period.start.slice(0,7);theme=p.theme==='light'?'light':'dark';view=p.view==='summary'?'summary':'detail';}catch{status('Görünüm tercihi okunamadı.',true);}
function savePrefs(){try{W.storage.setItem(prefsKey,JSON.stringify({...period,theme,view}));}catch{status('Görünüm tercihi kaydedilemedi.',true);}}
function setTheme(){document.body.dataset.homeTheme=theme;$('homeTheme').innerHTML=icon(theme==='dark'?'sun':'moon');$('homeTheme').setAttribute('aria-label',theme==='dark'?'Açık temaya geç':'Koyu temaya geç');}
function setView(){root.dataset.view=view;$('homeDetailed').setAttribute('aria-pressed',String(view==='detail'));$('homeCompact').setAttribute('aria-pressed',String(view==='summary'));savePrefs();}
function dateLabel(d){return new Date(d+'T12:00:00Z').toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'});}
function monthLabel(m){return new Date(m+'-15T12:00:00Z').toLocaleDateString('tr-TR',{month:'long',year:'numeric',timeZone:'Europe/Istanbul'});}
function money(n){return n===null?'Hesaplanamadı':n.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₺';}
function open(title,html){$('homeDialog').classList.remove('expanded');$('homeDialogTitle').textContent=title;$('homeDialogBody').innerHTML=html;if(!$('homeDialog').open)$('homeDialog').showModal();}
function close(){if(activeNote)saveNote();clearTimeout(noteTimer);activeNote=null;$('homeDialog').close();}
$('homeDialogClose').onclick=close;
function safeHtml(html){const tpl=document.createElement('template');tpl.innerHTML=String(html||'');const allowed=new Set(['B','STRONG','I','EM','U','UL','OL','LI','P','DIV','BR']);function clean(node){if(node.nodeType===3)return document.createTextNode(node.textContent);if(node.nodeType!==1)return document.createTextNode('');const tag=allowed.has(node.tagName)?node.tagName.toLowerCase():'span',el=document.createElement(tag);for(const child of node.childNodes)el.append(clean(child));return el;}const out=document.createElement('div');for(const n of tpl.content.childNodes)out.append(clean(n));return out.innerHTML.slice(0,50000);}
function loadNotes(){try{notes=window.SWHomeNotes.list();noteError='';}catch(e){notes=[];noteError=e.message;}}
function taskDate(n){return M.day(n.taskDay)||M.day(n.due)||(n.created?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Istanbul'}).format(new Date(n.created)):'');}
function showNotes(){loadNotes();const list=notes.filter(n=>n.column==='permanent');$('homePinned').innerHTML=noteError?`<p class="home-empty">${esc(noteError)}</p>`:list.slice(0,4).map(n=>`<button class="home-pin-row" data-note="${esc(n.id)}"><strong>${esc(n.title)}</strong><span>${esc(n.body.slice(0,90))}</span><i>↗</i></button>`).join('')||'<p class="home-empty">Henüz sabit not yok.</p>';const tasks=notes.filter(n=>n.column==='today'&&taskDate(n)===taskDay).sort((a,b)=>(a.taskOrder??a.created)-(b.taskOrder??b.created));const done=tasks.filter(n=>n.done).length;$('homeTaskCount').textContent=`${done} / ${tasks.length}`;$('homeProgress').value=tasks.length?done/tasks.length*100:0;if($('homeTaskDay'))$('homeTaskDay').value=taskDay;$('homeTasks').innerHTML=tasks.slice(0,8).map((n,i)=>`<div class="home-task-row ${n.done?'done':''}"><button data-task-toggle="${esc(n.id)}" aria-label="${esc(n.title)} ${n.done?'geri al':'tamamla'}">${n.done?'✓':''}</button><button data-task-edit="${esc(n.id)}">${esc(n.title)}</button><button data-task-move="${esc(n.id)}" data-dir="-1" aria-label="Yukarı taşı" ${i===0?'disabled':''}>↑</button><button data-task-move="${esc(n.id)}" data-dir="1" aria-label="Aşağı taşı" ${i===tasks.length-1?'disabled':''}>↓</button></div>`).join('')||`<p class="home-empty">${esc(noteError||'Bu gün için görev yok.')}</p>`;const reminders=notes.filter(n=>n.remind&&n.due&&!n.done).sort((a,b)=>a.due.localeCompare(b.due));$('homeReminders').innerHTML=reminders.slice(0,4).map(n=>`<button data-reminder="${esc(n.id)}" class="home-reminder ${new Date(n.due)<new Date()?'overdue':''}"><time>${esc(new Date(n.due).toLocaleDateString('tr-TR',{day:'numeric',month:'short'}))}</time><span>${esc(n.title)}</span><small>${new Date(n.due)<new Date()?'Gecikti':'Yaklaşıyor'}</small></button>`).join('')||'<p class="home-empty">Yaklaşan hatırlatıcı yok.</p>';$('homeBadge').hidden=!reminders.length;$('homeBadge').textContent=reminders.length;}
function salesRows(){saleKey=W.companyId==='PUSULA'?'fc_sales_history_v1':W.companyId==='KIB'?'fc_sales_history_kib_v1':'fc_sales_history_'+W.companyId.toLowerCase()+'_v1';salesError='';try{return M.read(W.storage,saleKey,Array.isArray,[]);}catch{salesError='Satış geçmişi okunamadı.';return [];}}
function metric(label,value,unit,symbol,color,source){return `<button class="home-metric ${color}" ${source?`data-module="${source}"`: 'data-source-open="1"'}><span class="home-metric-icon">${icon(symbol)}</span><span><span class="home-metric-label">${label}</span><strong>${value===null?'—':esc(String(value))}${unit||''}</strong></span></button>`;}
function data(){try{invoice=window.SWInvoiceBridge.snapshot();}catch{invoice={rows:[],rawError:'Fatura listesi okunamadı.'};}const available=invoice.rows.length>0&&!invoice.rawError&&!invoice.loading;invoiceStats=M.invoices(invoice.rows,period);const history=salesRows();salesData=M.sales(history,W.companyId,period);const total=available?invoiceStats.rows.length:null;const revenue=salesError||!salesData.rows.length?null:salesData.total;$('homeMetrics').innerHTML=metric('Toplam E-Fatura',total,'','stack','blue',available?'efatura':'')+metric('Satın Alma',null,'','coins','green','')+metric('Satış',salesError?null:salesData.rows.length,'','coins','teal','satis')+metric('KDV-2',null,'','coins','purple','')+metric('Dönem Ciro',revenue===null?null:money(revenue),'','chart','green','satis')+metric('Dönem Gider',null,'','chart','blue','');
const periodRows=[['Satışlar (aktarılan)',revenue],['Alımlar',null],['Giderler',null],['KDV-2',null]];$('homeFinance').innerHTML=periodRows.map(([label,v])=>`<div class="home-finance-row"><span>${label}</span><strong class="${v===null?'unavailable':''}">${money(v)}</strong></div>`).join('');const modules=[['efatura','Gelen E-Fatura Takip',total,'blue'],['satis','Satış Faturaları',salesError?null:salesData.rows.length,'green'],['masraf','Masraf Fişleri',null,'amber'],['yevmiye','Yurt Dışı Yevmiye',null,'purple'],['mutabakat','Cari Mutabakat',null,'teal']];$('homeSummary').innerHTML=modules.map(([id,label,v,color])=>`<button class="home-module-row ${color}" data-module="${id}">${icon('stack')}<span>${label}</span><b>${v===null?'—':v}</b><small>${v===null?'Veri yok':'Kayıt'}</small></button>`).join('');const recent=salesData.rows.map(r=>({date:M.day(r.tarih),doc:r.docNo||'Satış faturası'})).sort((a,b)=>b.date.localeCompare(a.date));$('homeRecent').innerHTML=recent.slice(0,5).map(r=>`<button data-module="satis" class="home-recent-row">${icon('note')}<span>Satış aktarımı – ${esc(r.doc)}</span><time>${dateLabel(r.date)}</time></button>`).join('')||'<p class="home-empty">Bu dönemde kaydedilmiş satış işlemi yok.</p>';$('homeSourceCaption').textContent='E-fatura: açık Takip listesi · Satış: firma satış geçmişi · —: doğrulanmış dönemsel veri bulunamadı';renderCharts(available);}
function renderCharts(available){const weeks=[0,1,2,3,4].map(i=>({label:`${i+1}. Hafta`,incoming:0,sales:0}));if(available)for(const r of invoiceStats.rows){const d=M.day(r.tarih);if(d)weeks[Math.min(4,Math.floor((+d.slice(8)-1)/7))].incoming++;}for(const r of salesData.rows){const d=M.day(r.tarih);if(d)weeks[Math.min(4,Math.floor((+d.slice(8)-1)/7))].sales++;}const max=Math.max(1,...weeks.flatMap(w=>[w.incoming,w.sales]));$('homeTrend').innerHTML=available||salesData.rows.length?`<div class="home-chart-key"><span>● Gelen E-Fatura</span><span>● Satış</span></div><div class="home-bars">${weeks.map(w=>`<div class="home-bar-week"><div><i style="height:${(w.incoming?w.incoming/max*100:0)}%" title="${w.incoming} gelen e-fatura"></i><i style="height:${(w.sales?w.sales/max*100:0)}%" title="${w.sales} satış"></i></div><small>${w.label}</small></div>`).join('')}</div>`:`<div class="home-blank-state"><span>${icon('chart')}</span><strong>Henüz grafik verisi yok</strong><small>Bu döneme ait işlemler geldikçe haftalık eğilim görünür.</small></div>`;const a=available?invoiceStats.rows.length:0,b=salesData.rows.length,sum=a+b;$('homeDistribution').innerHTML=sum?`<div class="home-donut-wrap"><div class="home-donut" style="--part:${Math.round(a/sum*100)}%"><strong>${sum}</strong><small>İşlem</small></div><div class="home-donut-key"><button data-module="efatura"><i class="dot blue"></i>Gelen E-Fatura <b>${a}</b></button><button data-module="satis"><i class="dot green"></i>Satış Aktarımı <b>${b}</b></button><p>Yalnızca kayıt sayısı doğrulanan iki kaynak.</p></div></div>`:`<div class="home-blank-state"><span>${icon('pie')}</span><strong>Henüz dağılım verisi yok</strong><small>Kaydedilen işlemlerin modül payları burada görünür.</small></div>`;}
function renderPeriod(){$('homePeriodLabel').textContent=monthLabel(month);$('homeFilterSummary').textContent=W.companyName+' | '+(period.start===M.monthRange(month).start&&period.end===M.monthRange(month).end?monthLabel(month):dateLabel(period.start)+' – '+dateLabel(period.end));$('homeRangeClear').hidden=period.start===M.monthRange(month).start&&period.end===M.monthRange(month).end;data();savePrefs();}
function periodDialog(){open('Dönem seç',`<form id="homePeriodForm"><label>Ay ve yıl<input type="month" id="homeMonthInput" value="${month}" required></label><button type="button" id="homeMonthApply">Ayın tamamı</button><div class="home-form-pair"><label>Başlangıç<input type="date" id="homeStart" value="${period.start}" required></label><label>Bitiş<input type="date" id="homeEnd" value="${period.end}" required></label></div><p id="homeFormError" role="alert"></p><footer><button type="submit">Aralığı uygula</button></footer></form>`);$('homeMonthApply').onclick=()=>{try{month=$('homeMonthInput').value;period=M.monthRange(month);renderPeriod();close();}catch(e){$('homeFormError').textContent=e.message;}};$('homePeriodForm').onsubmit=e=>{e.preventDefault();try{period=M.range($('homeStart').value,$('homeEnd').value);month=period.start.slice(0,7);renderPeriod();close();}catch(err){$('homeFormError').textContent=err.message;}};}
function formatLoad(){formatRaw=W.storage.getItem(formatKey);formatMap=formatRaw?JSON.parse(formatRaw):{};if(!formatMap||typeof formatMap!=='object'||Array.isArray(formatMap))throw Error('Not biçimleri okunamadı.');}
function formatSave(){if(W.storage.getItem(formatKey)!==formatRaw)throw Error('Not biçimleri başka sekmede değişti. Yeniden açın.');const value=JSON.stringify(formatMap);W.storage.setItem(formatKey,value);formatRaw=value;}
function richToolbar(){return `<div class="home-rich-toolbar"><select data-format-setting="font" aria-label="Yazı tipi"><option value="sans">Sans</option><option value="serif">Serif</option><option value="hand">El yazısı</option></select><select data-format-setting="size" aria-label="Yazı boyutu">${[12,14,16,18,20,24].map(x=>`<option value="${x}">${x}px</option>`).join('')}</select><select data-format-setting="paper" aria-label="Kâğıt rengi"><option value="cream">Eski kâğıt</option><option value="white">Beyaz</option><option value="blue">Mavi</option></select><input type="color" data-format-setting="color" aria-label="Yazı rengi" value="#182235"><button data-rich="bold" aria-label="Kalın"><b>B</b></button><button data-rich="italic" aria-label="İtalik"><i>I</i></button><button data-rich="underline" aria-label="Altı çizili"><u>U</u></button><button data-rich="insertUnorderedList" aria-label="Madde işaretleri">•</button><button data-rich="insertOrderedList" aria-label="Numaralı liste">1.</button><button data-rich="justifyLeft" aria-label="Sola hizala">≡</button><button data-rich="justifyCenter" aria-label="Ortala">≡</button></div>`;}
function noteEditor(id='',notebookId=''){loadNotes();if(noteError){status(noteError,true);return;}let n=notes.find(x=>x.id===id);if(id&&!n){status('Not bulunamadı.',true);return;}try{formatLoad();}catch(e){status(e.message,true);return;}const fresh=!n;n=n||{id:crypto.randomUUID(),title:'',body:'',notebookId,column:'permanent',paper:'cream',ink:'black',category:'work',finish:'strike',created:Date.now(),done:false,remind:false,due:''};activeNote=n;const f=formatMap[n.id]||{},font=['sans','serif','hand'].includes(f.font)?f.font:'serif',size=[12,14,16,18,20,24].includes(f.size)?f.size:16,paper=['cream','white','blue'].includes(f.paper)?f.paper:'cream',color=/^#[0-9a-f]{6}$/i.test(f.color||'')?f.color:'#182235';open(fresh?'Yeni sabit not':'Sabit not',`<div class="home-note-tools"><button id="homeNoteMax" aria-label="Pencereyi büyüt">⤢</button>${fresh?'':`<button id="homeNoteDelete" class="home-danger">Sil</button>`}</div><label>Başlık<input id="homeNoteTitle" value="${esc(n.title)}" maxlength="160" placeholder="Not başlığı"></label>${richToolbar()}<div id="homeRichBody" class="home-rich-body paper-${paper} font-${font}" contenteditable="true" role="textbox" aria-label="Not içeriği" style="font-size:${size}px;color:${color}">${f.html?safeHtml(f.html):esc(n.body).replace(/\n/g,'<br>')}</div><p id="homeNoteState">${fresh?'Yeni not':'Kaydedildi'}</p>`);$('homeNoteMax').onclick=()=>$('homeDialog').classList.toggle('expanded');const body=$('homeRichBody');$('homeNoteTitle').addEventListener('input',scheduleNote);body.addEventListener('input',scheduleNote);for(const el of $('homeDialog').querySelectorAll('[data-format-setting]')){el.value=({font,size,paper,color})[el.dataset.formatSetting];el.addEventListener('change',()=>{body.className='home-rich-body paper-'+$('homeDialog').querySelector('[data-format-setting="paper"]').value+' font-'+$('homeDialog').querySelector('[data-format-setting="font"]').value;body.style.fontSize=$('homeDialog').querySelector('[data-format-setting="size"]').value+'px';body.style.color=$('homeDialog').querySelector('[data-format-setting="color"]').value;scheduleNote();});}if($('homeNoteDelete'))$('homeNoteDelete').onclick=()=>deleteNote(n);}
function scheduleNote(){clearTimeout(noteTimer);$('homeNoteState').textContent='Kaydediliyor…';noteTimer=setTimeout(saveNote,450);}
function saveNote(){if(!activeNote)return;try{const title=$('homeNoteTitle').value.trim(),body=$('homeRichBody').textContent.trim();if(!title){$('homeNoteState').textContent='Kaydetmek için başlık yazın.';return;}const id=activeNote.id;window.SWHomeNotes.put({...activeNote,title,body});activeNote={...activeNote,title,body};formatMap[id]={html:safeHtml($('homeRichBody').innerHTML),font:$('homeDialog').querySelector('[data-format-setting="font"]').value,size:Number($('homeDialog').querySelector('[data-format-setting="size"]').value),paper:$('homeDialog').querySelector('[data-format-setting="paper"]').value,color:$('homeDialog').querySelector('[data-format-setting="color"]').value};formatSave();$('homeNoteState').textContent='✓ Kaydedildi';showNotes();}catch(e){$('homeNoteState').textContent='Kaydedilemedi: '+e.message;}}
function deleteNote(n){clearTimeout(noteTimer);activeNote=null;open('Not silinsin mi?',`<p>“${esc(n.title)}” silinecek. Önceki sağlam yedek korunur.</p><footer><button id="homeDeleteCancel">Vazgeç</button><button id="homeDeleteConfirm" class="home-danger">Sil</button></footer>`);$('homeDeleteCancel').onclick=()=>noteEditor(n.id);$('homeDeleteConfirm').onclick=()=>{try{window.SWHomeNotes.remove(n.id);close();showNotes();status('Not silindi.');}catch(e){status(e.message,true);}};}
function taskEditor(id){loadNotes();const n=notes.find(x=>x.id===id);if(!n)return;open('Görevi düzenle',`<form id="homeTaskEditForm"><input id="homeTaskEditTitle" maxlength="160" required value="${esc(n.title)}"><footer><button type="button" id="homeTaskDelete" class="home-danger">Sil</button><button type="submit">Kaydet</button></footer></form>`);$('homeTaskEditForm').onsubmit=e=>{e.preventDefault();try{window.SWHomeNotes.put({...n,title:$('homeTaskEditTitle').value.trim()});close();showNotes();}catch(err){status(err.message,true);}};$('homeTaskDelete').onclick=()=>{open('Görev silinsin mi?',`<p>${esc(n.title)}</p><footer><button id="homeTaskDeleteConfirm" class="home-danger">Sil</button></footer>`);$('homeTaskDeleteConfirm').onclick=()=>{try{window.SWHomeNotes.remove(id);close();showNotes();}catch(err){status(err.message,true);}};};}
function reminderEditor(id=''){loadNotes();const n=notes.find(x=>x.id===id);open(n?'Hatırlatıcıyı düzenle':'Hatırlatıcı ekle',`<form id="homeReminderForm"><label>Başlık<input id="homeReminderTitle" maxlength="160" required value="${esc(n?.title||'')}"></label><label>Açıklama<textarea id="homeReminderBody">${esc(n?.body||'')}</textarea></label><label>Tarih ve saat<input id="homeReminderDue" type="datetime-local" required value="${esc(n?.due||'')}"></label><label class="home-checkbox"><input id="homeReminderDone" type="checkbox" ${n?.done?'checked':''}> Tamamlandı</label><footer>${n?'<button type="button" id="homeReminderDelete" class="home-danger">Sil</button>':''}<button type="submit">Kaydet</button></footer></form>`);$('homeReminderForm').onsubmit=e=>{e.preventDefault();try{window.SWHomeNotes.put({...n,id:n?.id||crypto.randomUUID(),title:$('homeReminderTitle').value.trim(),body:$('homeReminderBody').value,due:$('homeReminderDue').value,remind:true,done:$('homeReminderDone').checked,column:n?.column||'week'});close();showNotes();}catch(err){status(err.message,true);}};if(n)$('homeReminderDelete').onclick=()=>deleteNote(n);}
function allNotes(){loadNotes();open('Sabit Notlar',`<div class="home-dialog-list">${notes.filter(n=>n.column==='permanent').map(n=>`<button data-note="${esc(n.id)}">${esc(n.title)}</button>`).join('')||'<p>Not yok.</p>'}</div><footer><button data-home-add="permanent">＋ Not ekle</button><button id="homeNotesExport">Yedek indir</button><button id="homeNotesRestore">Yedekten ekle</button></footer>`);$('homeNotesExport').onclick=()=>$('ntBackup').click();$('homeNotesRestore').onclick=()=>$('ntRestore').click();}
function allReminders(){loadNotes();open('Hatırlatıcılar',`<div class="home-dialog-list">${notes.filter(n=>n.remind&&n.due).map(n=>`<button data-reminder="${esc(n.id)}">${esc(n.title)} · ${esc(n.due)}</button>`).join('')||'<p>Hatırlatıcı yok.</p>'}</div><footer><button data-home-add="reminder">＋ Hatırlatıcı ekle</button></footer>`);}
function bookStore(){const raw=W.storage.getItem(bookKey),items=raw?JSON.parse(raw):[];if(!Array.isArray(items)||items.some(b=>!b||typeof b.id!=='string'||typeof b.name!=='string'))throw Error('Not defterleri okunamad?.');return {raw,items};}
function bookWrite(expected,items){if(W.storage.getItem(bookKey)!==expected)throw Error('Defterler ba?ka sekmede de?i?ti. Yeniden a??n.');W.storage.setItem(bookKey,JSON.stringify(items));}
function books(){loadNotes();let store;try{store=bookStore();}catch(e){status(e.message,true);return;}open('Not Defterleri',`<div class="home-dialog-list">${store.items.map(b=>`<button data-book="${esc(b.id)}">${esc(b.name)} ? ${notes.filter(n=>n.notebookId===b.id).length} not</button>`).join('')||'<p>Defter yok.</p>'}</div><footer><button id="homeBookNew">? Defter olu?tur</button><button id="homeBooksAll">T?m notlar</button></footer>`);$('homeBooksAll').onclick=allNotes;$('homeBookNew').onclick=()=>bookForm();}
function bookForm(id=''){let store;try{store=bookStore();}catch(e){status(e.message,true);return;}const book=store.items.find(b=>b.id===id);open(book?'Defter ad?n? de?i?tir':'Defter olu?tur',`<form id="homeBookForm"><label>Defter ad?<input id="homeBookName" maxlength="80" required value="${esc(book?.name||'')}"></label><footer><button type="submit">Kaydet</button></footer></form>`);$('homeBookForm').onsubmit=e=>{e.preventDefault();try{const name=$('homeBookName').value.trim();if(!name)return;bookWrite(store.raw,book?store.items.map(b=>b.id===id?{...b,name}:b):[...store.items,{id:crypto.randomUUID(),name}]);books();}catch(err){status(err.message,true);}};}
function bookOpen(id){loadNotes();let store;try{store=bookStore();}catch(e){status(e.message,true);return;}const b=store.items.find(x=>x.id===id);if(!b){books();return;}const list=notes.filter(n=>n.notebookId===id);open(b.name,`<div class="home-dialog-list">${list.map(n=>`<button data-note="${esc(n.id)}">${esc(n.title)}</button>`).join('')||'<p>Bu defterde not yok.</p>'}</div><footer><button id="homeBookNote">? Not ekle</button><button id="homeBookRename">Ad?n? de?i?tir</button><button id="homeBookDelete" class="home-danger">Defteri kald?r</button></footer>`);$('homeBookNote').onclick=()=>noteEditor('',id);$('homeBookRename').onclick=()=>bookForm(id);$('homeBookDelete').onclick=()=>{open('Defter kald?r?ls?n m??',`<p>??indeki notlar silinmez; di?er notlarda kal?r.</p><footer><button id="homeBookRemoveConfirm" class="home-danger">Defteri kald?r</button></footer>`);$('homeBookRemoveConfirm').onclick=()=>{try{bookWrite(store.raw,store.items.filter(x=>x.id!==id));books();}catch(err){status(err.message,true);}};};}
function quickLoad(){try{quickRaw=W.storage.getItem(quickKey)||'';const q=quickRaw?JSON.parse(quickRaw):{html:''};$('homeQuickEditor').innerHTML=safeHtml(q.html||'');quickSettings={font:['sans','serif','hand'].includes(q.font)?q.font:'sans',size:[12,14,16,18,20,24].includes(q.size)?q.size:14};$('homeQuickEditor').style.fontSize=quickSettings.size+'px';$('homeQuickEditor').style.fontFamily=quickSettings.font==='serif'?'Georgia,serif':quickSettings.font==='hand'?'Segoe Print,cursive':'Arial,sans-serif';}catch{$('homeQuickState').textContent='Not defteri okunamadı; kayıt üzerine yazılmadı.';$('homeQuickEditor').contentEditable='false';}}
function quickSave(){try{const existing=W.storage.getItem(quickKey)||'';if(existing!==quickRaw)throw Error('Başka sekmede değişti; yenileyin.');const raw=JSON.stringify({html:safeHtml($('homeQuickEditor').innerHTML),...quickSettings});W.storage.setItem(quickKey,raw);quickRaw=raw;$('homeQuickState').textContent='✓ Kaydedildi';}catch(e){$('homeQuickState').textContent='Kaydedilemedi: '+e.message;}}
function search(){const q=$('homeSearch').value.trim().toLocaleLowerCase('tr-TR');if(!q)return;loadNotes();const ns=notes.filter(n=>(n.title+' '+n.body).toLocaleLowerCase('tr-TR').includes(q)),sales=salesData.rows.filter(r=>String(r.docNo||'').toLocaleLowerCase('tr-TR').includes(q));open('Arama sonuçları',`<h3>Notlar</h3>${ns.map(n=>`<button data-note="${esc(n.id)}">${esc(n.title)}</button>`).join('')||'<p>Sonuç yok.</p>'}<h3>Satış işlemleri</h3>${sales.map(r=>`<button data-module="satis">${esc(r.docNo||'Satış faturası')}</button>`).join('')||'<p>Sonuç yok.</p>'}`);}
function navigate(page){close();if(page==='masraf'){document.querySelector('aside a[href$="/masraf/"]')?.click();return;}showPage(page);}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.homeMonth){const d=new Date(month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.homeMonth));month=d.toISOString().slice(0,7);period=M.monthRange(month);renderPeriod();}else if(b.dataset.note)noteEditor(b.dataset.note);else if(b.dataset.reminder)reminderEditor(b.dataset.reminder);else if(b.dataset.taskToggle){try{const n=notes.find(x=>x.id===b.dataset.taskToggle);window.SWHomeNotes.toggle(n.id,!n.done);showNotes();}catch(err){status(err.message,true);}}else if(b.dataset.taskEdit)taskEditor(b.dataset.taskEdit);else if(b.dataset.taskMove){const tasks=notes.filter(n=>n.column==='today'&&taskDate(n)===taskDay).sort((a,b)=>(a.taskOrder??a.created)-(b.taskOrder??b.created)),i=tasks.findIndex(n=>n.id===b.dataset.taskMove),j=i+Number(b.dataset.dir);if(j>=0&&j<tasks.length){try{const a=tasks[i].taskOrder??tasks[i].created,z=tasks[j].taskOrder??tasks[j].created;window.SWHomeNotes.put({...tasks[i],taskOrder:z});window.SWHomeNotes.put({...tasks[j],taskOrder:a});showNotes();}catch(err){status(err.message,true);}}}else if(b.dataset.module)navigate(b.dataset.module);else if(b.dataset.sourceOpen) $('homeSources').click();else if(b.dataset.homeAdd) b.dataset.homeAdd==='reminder'?reminderEditor():noteEditor();});
  $('homeDialog').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.note)noteEditor(b.dataset.note);else if(b.dataset.reminder)reminderEditor(b.dataset.reminder);else if(b.dataset.book)bookOpen(b.dataset.book);else if(b.dataset.weatherCity)selectWeatherCity(b.dataset.weatherCity);else if(b.dataset.module)navigate(b.dataset.module);else if(b.dataset.homeAdd) b.dataset.homeAdd==='reminder'?reminderEditor():noteEditor();else if(b.dataset.rich){e.preventDefault();const target=$('homeRichBody')||$('homeQuickLarge');target?.focus();document.execCommand(b.dataset.rich,false,null);if(activeNote)scheduleNote();else if($('homeQuickLarge')){ $('homeQuickEditor').innerHTML=safeHtml($('homeQuickLarge').innerHTML);clearTimeout(quickTimer);quickTimer=setTimeout(quickSave,450);}}});
$('homeDialog').addEventListener('mousedown',e=>{if(e.target.closest('[data-rich]'))e.preventDefault();});
$('homeTaskForm').onsubmit=e=>{e.preventDefault();const title=$('homeTaskEntry').value.trim();if(!title)return;try{window.SWHomeNotes.put({id:crypto.randomUUID(),title,body:'',column:'today',taskDay,paper:'cream',ink:'black',category:'work',finish:'strike',created:Date.now(),done:false,remind:false,due:'',taskOrder:Date.now()});$('homeTaskEntry').value='';showNotes();}catch(err){status(err.message,true);}};
const homeTaskDayInput=$('homeTaskDay');if(homeTaskDayInput)homeTaskDayInput.onchange=()=>{if(M.day(homeTaskDayInput.value)){taskDay=homeTaskDayInput.value;showNotes();}};
$('homeDetailed').onclick=()=>{view='detail';setView();};$('homeCompact').onclick=()=>{view='summary';setView();};$('homeTheme').onclick=()=>{theme=theme==='dark'?'light':'dark';setTheme();savePrefs();};$('homePeriodOpen').onclick=periodDialog;$('homeDateOpen').onclick=periodDialog;$('homeRangeClear').onclick=()=>{period=M.monthRange(month);renderPeriod();};$('homeAllNotes').onclick=allNotes;$('homeReminderAll').onclick=allReminders;$('homeNotifications').onclick=allReminders;$('homeBookAdd').onclick=books;$('homeRecentAll').onclick=()=>navigate('satis');$('homeProfile').onclick=()=>{if(window.SW_CONTEXT)location.href='/account';else open('Yerel çalışma alanı',`<p>${esc(W.companyName)} kayıtları bu cihazda tutulur.</p>`);};$('homeQuickExpand').onclick=()=>{open('Hızlı Not Defteri',richToolbar()+'<div id="homeQuickLarge" contenteditable="true" class="home-rich-body paper-cream" role="textbox" aria-label="Hızlı not defteri"></div><p id="homeQuickLargeState">Otomatik kaydedilir.</p>');$('homeDialog').classList.add('expanded');$('homeQuickLarge').innerHTML=safeHtml($('homeQuickEditor').innerHTML);const quickFont=$('homeDialog').querySelector('[data-format-setting=font]'),quickSize=$('homeDialog').querySelector('[data-format-setting=size]');quickFont.value=quickSettings.font;quickSize.value=quickSettings.size;const applyQuick=()=>{quickSettings={font:quickFont.value,size:Number(quickSize.value)};$('homeQuickLarge').className='home-rich-body font-'+quickSettings.font;$('homeQuickLarge').style.fontSize=quickSettings.size+'px';$('homeQuickEditor').style.fontSize=quickSettings.size+'px';$('homeQuickEditor').style.fontFamily=quickSettings.font==='serif'?'Georgia,serif':quickSettings.font==='hand'?'Segoe Print,cursive':'Arial,sans-serif';clearTimeout(quickTimer);quickTimer=setTimeout(quickSave,450);};quickFont.onchange=applyQuick;quickSize.onchange=applyQuick;applyQuick();$('homeQuickLarge').oninput=()=>{ $('homeQuickEditor').innerHTML=safeHtml($('homeQuickLarge').innerHTML);clearTimeout(quickTimer);quickTimer=setTimeout(quickSave,450);$('homeQuickLargeState').textContent='Kaydediliyor…';};};$('homeQuickEditor').oninput=()=>{clearTimeout(quickTimer);$('homeQuickState').textContent='Kaydediliyor…';quickTimer=setTimeout(quickSave,450);};$('homeSearchForm').onsubmit=e=>{e.preventDefault();search();};
$('homeSources').onclick=()=>open('Veri kaynakları',`<p>Gelen E-Fatura Takip açık listesinin fatura tarihi ve aktif firmanın satış aktarım geçmişi kullanılır. İzibiz ayrıca toplanmaz.</p><p>Satın alma, masraf, KDV ve diğer modüller için güvenilir ortak dönem toplamı yoksa — gösterilir. Grafiklerde yalnızca doğrulanmış kayıtlar bulunur.</p><p>Notlar, görevler ve Hızlı Not Defteri aktif firmanın tarayıcı kaydındadır. Hatırlatma bildirimi yalnızca uygulama açıkken çalışır.</p>`);
function weatherAppearance(symbol){const code=String(symbol||'').toLowerCase();if(code.includes('thunder'))return ['⛈️','Gök gürültülü'];if(code.includes('snow')||code.includes('sleet'))return ['🌨️','Karlı'];if(code.includes('rain'))return ['🌧️','Yağmurlu'];if(code.includes('fog'))return ['🌫️','Sisli'];if(code.includes('partlycloudy'))return ['⛅','Parçalı bulutlu'];if(code.includes('cloudy'))return ['☁️','Bulutlu'];if(code.includes('fair'))return ['🌤️','Az bulutlu'];return code.includes('night')?['🌙','Açık']:['☀️','Açık'];}
async function loadWeather(){const city=weatherCity;$('homeWeatherCity').textContent=city+' ▾';$('homeWeatherText').textContent='Yükleniyor';try{const response=await fetch('/api/weather?city='+encodeURIComponent(city),{credentials:'same-origin',signal:AbortSignal.timeout(12000)});if(response.status===503){$('homeWeatherIcon').textContent='?';$('homeWeatherTemp').textContent='--?';$('homeWeatherText').textContent='Hazırlanıyor';return;}if(!response.ok)throw Error('Hava durumu alınamadı.');const data=await response.json();if(city!==weatherCity)return;if(data.city!==city||!Number.isFinite(data.temperature))throw Error('Hava durumu okunamadı.');const [emoji,label]=weatherAppearance(data.symbol);$('homeWeatherIcon').textContent=emoji;$('homeWeatherTemp').textContent=data.temperature+'°';$('homeWeatherText').textContent=label;$('homeWeatherText').title=Number.isFinite(data.minimum)&&Number.isFinite(data.maximum)?`Bugün ${data.minimum}°–${data.maximum}°`:label;$('homeWeatherCredit').title='MET Norway verisi · CC BY 4.0 · günlük kart için özetlendi';}catch{if(city===weatherCity){$('homeWeatherIcon').textContent='☁️';$('homeWeatherTemp').textContent='--°';$('homeWeatherText').textContent='Veri alınamadı';}}}
function selectWeatherCity(city){if(!weatherCities.includes(city))return;weatherCity=city;try{W.storage.setItem(weatherKey,city);}catch{}close();loadWeather();}
$('homeWeatherCity').onclick=()=>open('Hava durumu şehri',`<div class="home-dialog-list">${weatherCities.map(city=>`<button data-weather-city="${esc(city)}">${esc(city)}</button>`).join('')}</div>`);
function sidebarTools(){showPage('home');open('Araçlar',`<div class="home-dialog-list"><button id="homeToolPeriod">Dönem seç</button><button id="homeToolBooks">Not defterleri</button><button id="homeToolReminders">Hatırlatıcılar</button></div>`);$('homeToolPeriod').onclick=periodDialog;$('homeToolBooks').onclick=books;$('homeToolReminders').onclick=allReminders;}
$('homeNavReports')?.addEventListener('click',()=>{showPage('home');view='summary';setView();});
$('homeNavTools')?.addEventListener('click',sidebarTools);
$('homeNavSettings')?.addEventListener('click',()=>{if(window.SW_CONTEXT)location.href='/account';else open('Ayarlar',`<p>Yerel çalışma alanı ayarları bu cihazda tutulur.</p>`);});
$('homeNavHelp')?.addEventListener('click',()=>{showPage('home');open('Yardım',`<p>Üstteki ay veya tarih alanına tıklayarak dönem seçebilirsiniz.</p><p>Raporlar, dönem özetini açar. Araçlar üzerinden not defterlerine ve hatırlatıcılara ulaşabilirsiniz.</p>`);});
function clock(){const now=new Date();$('homeToday').textContent=now.toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul',day:'numeric',month:'long',year:'numeric',weekday:'long'});$('homeTime').textContent=now.toLocaleTimeString('tr-TR',{timeZone:'Europe/Istanbul',hour:'2-digit',minute:'2-digit'});}function refresh(){if(document.body.classList.contains('fc-home-full')){showNotes();renderPeriod();}}document.addEventListener('sw:notes-changed',showNotes);window.addEventListener('storage',e=>{if(e.key?.startsWith('sw:company:v2:'+W.companyId+':'))refresh();});new MutationObserver(refresh).observe(root,{attributes:true,attributeFilter:['style']});$('homeDialog').addEventListener('close',()=>{$('homeDialog').classList.remove('expanded');clearTimeout(noteTimer);if(activeNote)saveNote();activeNote=null;});setTheme();setView();clock();setInterval(clock,1000);quickLoad();showNotes();renderPeriod();loadWeather();setInterval(()=>{if(document.body.classList.contains('fc-home-full'))loadWeather();},1800000);
})();
